'use client';
// <BrandOrb>: thinking-orbs by Jakub Antalik (MIT, libraries.dev/orbs) in your
// brand colours. Generated by product-aesthetics; regenerate with
//   pa add thinking-orbs --brand <your brand file>
//
// Geometry, sizes, speed, pause, offscreen and reduced-motion handling are the
// library's own; only the ink changes. Every dot the library draws carries an
// ink value `white`: 0 = nearest the viewer, 1 = faded into the page.
//   light page: nearest dots in your text colour, the body in your primary,
//               the far side fading out
//   dark page:  your dark-scheme primary throughout, fading out
// The fade is transparency, not a mix toward a page colour, so the orb sits
// cleanly on any background in its family.
import { jsx } from 'react/jsx-runtime';
import { useEffect, useRef, useState } from 'react';
import { MODE_FRAMES, resolvePreset, scaleCounts, scaleRadii } from 'thinking-orbs';

/* brand:start */
export const BRAND = { name: 'Stock grey', light: { ink: '#18181b', body: '#71717a' }, dark: { body: '#d4d4d8' }, theme: 'auto' };
/* brand:end */

const NEAR = 0.12; // pure ink up to here (light pages only)
const BODY = 0.24; // pure body colour from here
const FADE = 0.45; // fades out from here to the back

const rgb = (hex) => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
const INK = rgb(BRAND.light.ink);
const BODY_LIGHT = rgb(BRAND.light.body);
const BODY_DARK = rgb(BRAND.dark.body);

/** The colour for one dot or line, given its ink value and alpha. */
export function brandInk(white, alpha, dark) {
  const w = Math.min(1, Math.max(0, white));
  let c = dark ? BODY_DARK : BODY_LIGHT;
  if (!dark && w < BODY) {
    const f = Math.max(0, (w - NEAR) / (BODY - NEAR));
    c = INK.map((v, i) => Math.round(v + (BODY_LIGHT[i] - v) * f));
  }
  const a = w > FADE ? alpha * (1 - (w - FADE) / (1 - FADE)) : alpha;
  return `rgba(${c[0]},${c[1]},${c[2]},${a})`;
}

/** Paint a finished frame (from MODE_FRAMES) in brand colours. Lines first, so dots sit on top. */
export function paintBrand(ctx, frame, dark) {
  for (const l of frame.lines) {
    ctx.strokeStyle = brandInk(l.white, l.a ?? 1, dark);
    ctx.lineWidth = l.w;
    ctx.beginPath();
    ctx.moveTo(l.x1, l.y1);
    ctx.lineTo(l.x2, l.y2);
    ctx.stroke();
  }
  for (const d of frame.dots) {
    ctx.fillStyle = brandInk(d.white, d.a ?? 1, dark);
    ctx.beginPath();
    ctx.arc(d.x, d.y, d.r, 0, Math.PI * 2);
    ctx.fill();
  }
}

const LABELS = {
  working: 'Working…',
  searching: 'Searching…',
  solving: 'Solving…',
  listening: 'Listening…',
  connecting: 'Connecting…',
  weaving: 'Weaving…',
  composing: 'Composing…',
  breathing: 'Thinking…',
  shaping: 'Shaping…',
};

function ancestorTheme(el) {
  for (let node = el; node; node = node.parentElement) {
    const attr = node.getAttribute('data-theme');
    if (attr === 'dark') return true;
    if (attr === 'light') return false;
    if (node.classList.contains('dark')) return true;
    if (node.classList.contains('light')) return false;
  }
  return null;
}

// 'light' and 'dark' pin the palette; 'auto' follows an ancestor's
// data-theme / dark class, then the OS setting, as the stock orb does.
function useDark(theme, ref) {
  const [dark, setDark] = useState(theme === 'dark');
  useEffect(() => {
    if (theme !== 'auto') {
      setDark(theme === 'dark');
      return;
    }
    const mq = typeof matchMedia !== 'undefined' ? matchMedia('(prefers-color-scheme: dark)') : null;
    const resolve = () => setDark(ancestorTheme(ref.current) ?? !!mq?.matches);
    resolve();
    mq?.addEventListener('change', resolve);
    const mo = typeof MutationObserver !== 'undefined' ? new MutationObserver(resolve) : null;
    mo?.observe(document.documentElement, { attributes: true, attributeFilter: ['class', 'data-theme'], subtree: true });
    return () => {
      mq?.removeEventListener('change', resolve);
      mo?.disconnect();
    };
  }, [theme]);
  return dark;
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    if (typeof matchMedia === 'undefined') return;
    const mq = matchMedia('(prefers-reduced-motion: reduce)');
    setReduced(mq.matches);
    const on = (e) => setReduced(e.matches);
    mq.addEventListener('change', on);
    return () => mq.removeEventListener('change', on);
  }, []);
  return reduced;
}

export function BrandOrb({
  state = 'working',
  size = 64,
  theme = BRAND.theme,
  speed = 1,
  paused = false,
  dots = 1,
  dotSize = 1,
  opts: optsOverride,
  style,
  'aria-label': ariaLabel,
  ...rest
}) {
  const ref = useRef(null);
  const dark = useDark(theme, ref);
  const reduced = useReducedMotion();
  const optsKey = optsOverride ? JSON.stringify(optsOverride) : '';

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const dpr = Math.min(2, (typeof devicePixelRatio !== 'undefined' && devicePixelRatio) || 1);
    canvas.width = Math.round(size * dpr);
    canvas.height = Math.round(size * dpr);
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { mode, speed: baseSpeed, opts: presetOpts } = resolvePreset(state, size);
    let opts = dots !== 1 ? scaleCounts(presetOpts, Math.max(0.1, dots)) : presetOpts;
    if (dotSize !== 1) opts = scaleRadii(opts, Math.max(0.1, dotSize));
    if (optsOverride) opts = { ...opts, ...optsOverride };
    const frameFn = MODE_FRAMES[mode];
    const effSpeed = baseSpeed * speed;

    const draw = (t) => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, size, size);
      paintBrand(ctx, frameFn(size, t, opts), dark);
    };
    if (reduced) {
      draw(0.6);
      return;
    }

    // One shared clock (performance.now), so every orb on a page stays in phase.
    let raf = 0;
    let running = false;
    const loop = () => {
      draw((performance.now() / 1000) * effSpeed);
      if (running) raf = requestAnimationFrame(loop);
    };
    const start = () => {
      if (running || paused) return;
      running = true;
      raf = requestAnimationFrame(loop);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };
    draw((performance.now() / 1000) * effSpeed);

    let visible = true;
    const io =
      typeof IntersectionObserver !== 'undefined'
        ? new IntersectionObserver(([entry]) => {
            visible = entry.isIntersecting;
            if (visible && document.visibilityState !== 'hidden') start();
            else stop();
          })
        : null;
    io?.observe(canvas);
    const onVis = () => {
      if (document.visibilityState === 'hidden') stop();
      else if (visible) start();
    };
    document.addEventListener('visibilitychange', onVis);
    if (!io) start();
    return () => {
      stop();
      io?.disconnect();
      document.removeEventListener('visibilitychange', onVis);
    };
  }, [state, size, dark, speed, paused, reduced, dots, dotSize, optsKey]);

  return jsx('canvas', {
    ref,
    role: 'img',
    'aria-label': ariaLabel ?? LABELS[state],
    style: { width: size, height: size, display: 'block', ...style },
    ...rest,
  });
}
